head.script:
scwin.trigger1_onclick = function(e) {
    $w.executeWhilst("submission1", condFn, 10, "loading.....", finalDone, rejectFunc, "submissionWh");
};
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");	
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "3000");
    //Verify 3. 콘솔에 설정한 횟수만큼 (10 설정) submission 이 동작한다. (그림참고)
    //3. The number of times (10 settings) submission is set in the console. (See illustration)
    WebSquare.wUnit.addCommand("assert", "count == 10", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();

scwin.onpageload = function() {
    rejectFunc = function(e) {
        console.log('reject...');
    };
    finalDone = function(e) {
        console.log('done...');
    };
    window.count;
    condFn = function(id, idx) {
        console.log("whilstCond === " + id + "  idx : " + idx);
        count = idx;
        if (id == "submission1" && idx == 10) {
            return false;
        }
        return true;
    };
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 06-Feb-2018
    //End unitTest
}
